<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ArrowPathIcon, ArrowUpRightIcon, DocumentTextIcon, EllipsisHorizontalIcon, PlusIcon, ServerStackIcon, TrashIcon } from '@heroicons/vue/24/outline'
import PageHeader from '../components/PageHeader.vue'
import StatusBadge from '../components/StatusBadge.vue'
import { api } from '../lib/api'
import type { Application } from '../types'

const route = useRoute(); const applications = ref<Application[]>([]); const search = ref(''); const showDeploy = ref(false); const loading = ref(true); const actionId = ref<string | null>(null)
const step = ref(1); const form = ref({ name: '', namespace: 'staging', image: '', replicas: 2, port: 8080, ingressHost: '' })
onMounted(async () => { search.value = typeof route.query.q === 'string' ? route.query.q : ''; applications.value = await api.applications(); loading.value = false })
const filtered = computed(() => applications.value.filter((app) => [app.name, app.namespace, app.image].some((value) => value.toLowerCase().includes(search.value.toLowerCase()))))
const age = (date: string) => { const days = Math.max(1, Math.round((Date.now() - new Date(date).getTime()) / 86400000)); return days === 1 ? '1 day' : `${days} days` }
function resetWizard() { step.value = 1; form.value = { name: '', namespace: 'staging', image: '', replicas: 2, port: 8080, ingressHost: '' } }
async function deploy() { actionId.value = 'deploy'; try { const result = await api.deploy(form.value); applications.value.unshift(result) } catch { applications.value.unshift({ ...form.value, id: `local-${Date.now()}`, status: 'Progressing', availableReplicas: 0, ingressHost: form.value.ingressHost || null, createdAt: new Date().toISOString(), updatedAt: new Date().toISOString() }) } finally { actionId.value = null; showDeploy.value = false; resetWizard() } }
async function restart(app: Application) { actionId.value = app.id; await api.restart(app.id).catch(() => undefined); app.updatedAt = new Date().toISOString(); actionId.value = null }
async function scale(app: Application) { const value = window.prompt(`Scale ${app.name} to how many replicas?`, String(app.replicas)); const replicas = Number(value); if (!Number.isFinite(replicas) || replicas < 0) return; actionId.value = app.id; await api.scale(app.id, replicas).catch(() => undefined); app.replicas = replicas; app.availableReplicas = replicas; actionId.value = null }
async function remove(app: Application) { if (!window.confirm(`Delete ${app.name}?`)) return; actionId.value = app.id; await api.deleteApplication(app.id).catch(() => undefined); applications.value = applications.value.filter((item) => item.id !== app.id); actionId.value = null }
</script>

<template>
  <PageHeader eyebrow="Workloads" title="Applications" description="Deploy, scale, and operate your services across every environment."><button class="button-primary" @click="showDeploy = true"><PlusIcon class="h-4 w-4" />Deploy application</button></PageHeader>
  <div class="surface overflow-hidden"><div class="flex flex-col justify-between gap-3 border-b border-line/70 p-4 sm:flex-row sm:items-center sm:p-5"><div class="flex items-center gap-2"><div class="relative"><svg class="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="m20 20-4-4" stroke-linecap="round" /></svg><input v-model="search" class="field h-9 w-full pl-9 text-xs sm:w-72" placeholder="Filter applications..." /></div><span class="hidden rounded-full bg-white/[.04] px-2 py-1 text-[11px] text-slate-500 sm:inline">{{ filtered.length }} total</span></div><button class="button-ghost self-start text-xs sm:self-auto"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 6h16M7 12h10M10 18h4" stroke-linecap="round" /></svg>Filter</button></div><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left"><thead><tr class="text-[10px] uppercase tracking-[.16em] text-slate-600"><th class="px-5 py-3 font-semibold">Application</th><th class="px-3 py-3 font-semibold">Namespace</th><th class="px-3 py-3 font-semibold">Image</th><th class="px-3 py-3 font-semibold">Status</th><th class="px-3 py-3 font-semibold">Replicas</th><th class="px-3 py-3 font-semibold">Age</th><th class="px-5 py-3" /></tr></thead><tbody><tr v-if="loading"><td colspan="7" class="px-5 py-16 text-center text-sm text-slate-600">Loading applications...</td></tr><tr v-else-if="filtered.length === 0"><td colspan="7" class="px-5 py-16 text-center text-sm text-slate-600">No applications match your filter.</td></tr><tr v-for="app in filtered" :key="app.id" class="table-row"><td class="px-5 py-4"><div class="flex items-center gap-3"><div class="grid h-8 w-8 place-items-center rounded-lg bg-violet/10 text-violet"><ServerStackIcon class="h-4 w-4" /></div><div><p class="text-sm font-semibold text-slate-200">{{ app.name }}</p><p v-if="app.ingressHost" class="mt-0.5 flex items-center gap-1 text-[11px] text-accent">{{ app.ingressHost }} <ArrowUpRightIcon class="h-3 w-3" /></p><p v-else class="mt-0.5 text-[11px] text-slate-600">Internal service</p></div></div></td><td class="px-3 py-4"><span class="rounded-md bg-white/[.04] px-2 py-1 font-mono text-[11px] text-slate-400">{{ app.namespace }}</span></td><td class="max-w-[220px] px-3 py-4"><p class="truncate font-mono text-[11px] text-slate-500" :title="app.image">{{ app.image }}</p></td><td class="px-3 py-4"><StatusBadge :status="app.status" /></td><td class="px-3 py-4"><span class="font-mono text-xs text-slate-300">{{ app.availableReplicas }} / {{ app.replicas }}</span></td><td class="px-3 py-4 text-xs text-slate-500">{{ age(app.createdAt) }}</td><td class="px-5 py-4"><div class="flex justify-end gap-1"><button class="button-ghost" title="View logs" @click="$router.push({ path: '/logs', query: { application: app.name } })"><DocumentTextIcon class="h-4 w-4" /></button><button class="button-ghost" title="Restart" :disabled="actionId === app.id" @click="restart(app)"><ArrowPathIcon class="h-4 w-4" /></button><button class="button-ghost" title="Scale" @click="scale(app)"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 19V5m0 14h16M8 16v-5m4 5V8m4 8v-3" stroke-linecap="round" /></svg></button><button class="button-ghost text-slate-600 hover:text-rose-300" title="Delete" @click="remove(app)"><TrashIcon class="h-4 w-4" /></button><button class="button-ghost px-1"><EllipsisHorizontalIcon class="h-4 w-4" /></button></div></td></tr></tbody></table></div></div>
  <div class="mt-5 flex items-center gap-2 text-xs text-slate-600"><span class="h-1.5 w-1.5 rounded-full bg-accent" />Changes are reconciled through the Kubernetes control plane.</div>

  <Teleport to="body"><div v-if="showDeploy" class="fixed inset-0 z-50 flex items-center justify-center bg-black/75 p-4 backdrop-blur-sm"><div class="w-full max-w-xl rounded-2xl border border-line bg-[#0d1a2c] shadow-2xl"><div class="flex items-start justify-between border-b border-line p-6"><div><p class="eyebrow text-accent">New workload</p><h2 class="mt-2 text-xl font-bold text-white">Deploy application</h2></div><button class="button-ghost" @click="showDeploy = false"><svg class="h-5 w-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><path d="m6 6 12 12M18 6 6 18" stroke-linecap="round" /></svg></button></div><div class="flex items-center gap-2 px-6 pt-6"><div v-for="n in 5" :key="n" class="flex flex-1 items-center gap-2"><span :class="['grid h-6 w-6 place-items-center rounded-full text-[11px] font-bold', step >= n ? 'bg-accent text-ink' : 'bg-white/[.06] text-slate-600']">{{ n }}</span><div v-if="n < 5" :class="['h-px flex-1', step > n ? 'bg-accent/70' : 'bg-line']" /></div></div><div class="p-6"><div v-if="step === 1"><label class="mb-2 block text-xs font-semibold text-slate-300">Application name</label><input v-model="form.name" class="field" placeholder="e.g. checkout-api" autofocus /><p class="mt-2 text-xs text-slate-600">Lowercase letters, numbers, and hyphens only.</p></div><div v-else-if="step === 2" class="space-y-5"><div><label class="mb-2 block text-xs font-semibold text-slate-300">Container image</label><input v-model="form.image" class="field font-mono" placeholder="ghcr.io/acme/service:latest" /></div><div><label class="mb-2 block text-xs font-semibold text-slate-300">Namespace</label><select v-model="form.namespace" class="field"><option>staging</option><option>production</option><option>preview-pr-482</option></select></div></div><div v-else-if="step === 3"><label class="mb-2 block text-xs font-semibold text-slate-300">Initial replicas</label><div class="flex items-center gap-4"><input v-model.number="form.replicas" type="range" min="0" max="10" class="flex-1 accent-accent" /><span class="grid h-10 w-12 place-items-center rounded-lg border border-line font-mono text-sm text-white">{{ form.replicas }}</span></div><p class="mt-3 text-xs text-slate-600">You can scale this workload at any time.</p></div><div v-else-if="step === 4"><label class="mb-2 block text-xs font-semibold text-slate-300">Container port</label><input v-model.number="form.port" class="field" type="number" min="1" max="65535" /><p class="mt-2 text-xs text-slate-600">The Service will target this port.</p></div><div v-else><label class="mb-2 block text-xs font-semibold text-slate-300">Ingress hostname <span class="font-normal text-slate-600">(optional)</span></label><input v-model="form.ingressHost" class="field" placeholder="app.example.com" /><div class="mt-4 rounded-xl border border-accent/15 bg-accent/[.04] p-4 text-xs leading-5 text-slate-400">Vertex will create a Deployment, ClusterIP Service, and an Ingress when a hostname is provided.</div></div><div class="mt-8 flex justify-between"><button class="button-secondary" :disabled="step === 1" @click="step--">Back</button><button v-if="step < 5" class="button-primary" :disabled="(step === 1 && !form.name) || (step === 2 && !form.image)" @click="step++">Continue <ArrowUpRightIcon class="h-4 w-4" /></button><button v-else class="button-primary" :disabled="!form.name || !form.image || actionId === 'deploy'" @click="deploy">{{ actionId === 'deploy' ? 'Deploying...' : 'Deploy application' }}</button></div></div></div></div></Teleport>
</template>

